head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > skipConfirmOnly]<br/>Calendar 컴포넌트에서 확인 버튼의 표시 여부를 설정합니다.",
    "validation" : [
        "미설정(기본값 false) 시 skipConfirm 속성에 따라 확인 버튼의 표시 여부가 결정됩니다.",
        "true 설정 시 컴포넌트에 확인 버튼을 항상 표시합니다.",
        "true 설정 + calendarValueType='yearMonth' + renderType='component' 일때 월 SelectBox 변경 시 onconfirm 이벤트가 발생합니다.",
        "true 설정 + calendarValueType='yearMonthDate' 인 경우 확인 버튼은 항상 표시되지 않습니다.",
        "skipConfirmOnly 속성을 true 로 설정 시 skipConfirm 속성은 무시됩니다.",
        "skipConfirmOnly 속성은 skipConfirm=true 일 때와 동일한 기능을 제공하며 '확인' 버튼을 항상 표시합니다.",
        "skipConfirmOnly 속성과 동일 기능에 '확인' 버튼을 표시하지 않으려면 skipConfirm 속성을 설정해야 합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        skipConfirmOnly : con_skipConfirmOnly.getText(),
        skipConfirm : con_skipConfirm.getText(),
        calendarValueType : con_calendarValueType.getText(),
        renderType : con_renderType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick", "onconfirm"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



// 확인 버튼 DOM 존재 여부 확인 (skipConfirmOnly / skipConfirm / calendarValueType 조합 결과)
scwin.getConfirmButtonInfo = function () {
    let r = target1.render;
    // calendarValueType 별로 확인 버튼 DOM 클래스가 다름:
    // yearMonth/year → .w2calendar_header_btn_ok / .w2calendar_header_btn_ok_yearType
    // yearMonthDateHour/yearMonthDateTime/Sec → .w2calendar_time_confirm
    let confirmBtn = r.querySelector('[class*="w2calendar_header_btn_ok"]')
        || r.querySelector('[class*="w2calendar_time_confirm"]');

    // validation: skipConfirmOnly=true 이면 확인 버튼 항상 표시 (skipConfirm 속성 무시)
    //             단, calendarValueType='yearMonthDate' 인 경우는 확인 버튼이 항상 표시되지 않음
    //             skipConfirmOnly=false 이면 skipConfirm 속성에 따라 확인 버튼 표시 여부 결정
    wf_body_bottom.getObj("scwin").setReturnValue("[확인 버튼 표시 여부] " + (confirmBtn ? "표시됨" : "숨김"));
}



// 속성/DOM 정보 조회 버튼
scwin.btn_getInfo_onclick = function (e) {
    let skipConfirmOnly = target1.options.skipConfirmOnly;
    let skipConfirm = target1.options.skipConfirm;
    let calendarValueType = target1.options.calendarValueType;
    let renderType = target1.options.renderType;

    // validation: skipConfirmOnly=true 인 경우 skipConfirm 속성은 무시됨
    let skipConfirmEffective = (skipConfirmOnly === true || skipConfirmOnly === "true")
        ? "(skipConfirmOnly=true 로 인해 무시됨)"
        : String(skipConfirm);

    // validation: skipConfirmOnly 적용값 / skipConfirm 적용값 / 관련 속성값 확인
    wf_body_bottom.getObj("scwin").setReturnValue("[skipConfirmOnly 적용값] " + skipConfirmOnly
        + " / skipConfirm 적용값=" + skipConfirmEffective
        + " / calendarValueType=" + calendarValueType
        + " / renderType=" + renderType);

    scwin.getConfirmButtonInfo();

    // validation: 현재 입력값 확인
    wf_body_bottom.getObj("scwin").setReturnValue("[현재 입력값] target1.getValue() = " + target1.getValue());
}



// target1 클릭 시 (날짜 선택 등) 자동으로 입력값 확인
scwin.target1_onclick = function (e) {
    setTimeout(() => {
        // 날짜 선택 후 현재 입력값 확인
        wf_body_bottom.getObj("scwin").setReturnValue("[날짜 선택 후 입력값] target1.getValue() = " + target1.getValue());
    }, 100);
}



// 확인 버튼 클릭 또는 (skipConfirm/skipConfirmOnly=true + calendarValueType=yearMonth/year) 조건에서 onconfirm 이벤트 발생
scwin.target1_onconfirm = function (e) {
    // validation: true 설정 + calendarValueType='yearMonth' + renderType='component' 일때 월 SelectBox 변경 시 onconfirm 이벤트 발생
    // validation: '확인' 버튼 클릭 시 onconfirm 이벤트 발생
    wf_body_bottom.getObj("scwin").setReturnValue("[onconfirm 이벤트 발생] onconfirm 핸들러 호출됨");
}
